export const gates=[['behavior','Acceptance behavior'],['regression','Regression evidence'],['api','API & integration checks'],['human','Human exploration'],['access','Accessibility & usability'],['operations','Performance, security & recovery']];
export const gateStates=['Not reviewed','Evidence recorded','Blocked','Not applicable'];
export const recordFields=['title','context','hypothesis','oracle','experiment','observation','evidence','gaps','next','reviewer','conclusion'];
export const blankHuman=()=>({version:1,release:'',build:'',records:[],gates:Object.fromEntries(gates.map(([id])=>[id,{state:'Not reviewed',evidence:''}]))});
const text=(v,max=12000)=>{if(typeof v!=='string'||v.length>max)throw Error('Invalid or oversized text field.');return v;};
export function validateHuman(v){if(v?.version!==1||!Array.isArray(v.records)||v.records.length>200)throw Error('Invalid HIST workspace (maximum 200 investigations).');const out=blankHuman();out.release=text(v.release,300);out.build=text(v.build,300);const ids=new Set();out.records=v.records.map(r=>{const id=text(r.id,100);if(!id||ids.has(id))throw Error('Duplicate or missing investigation ID.');ids.add(id);if(!['Investigating','Reviewed'].includes(r.state)||!Number.isInteger(r.storyRevision)||r.storyRevision<0)throw Error('Invalid investigation state.');const row={id,at:text(r.at,60),storyId:text(r.storyId,100),storyRevision:r.storyRevision,state:r.state,...Object.fromEntries(recordFields.map(k=>[k,text(r[k],k==='title'?300:12000)]))};validateRecord(row);return row;});for(const [id]of gates){const g=v.gates?.[id];if(!g||!gateStates.includes(g.state))throw Error('Invalid release review status.');out.gates[id]={state:g.state,evidence:text(g.evidence,4000)};if(g.state!=='Not reviewed'&&!g.evidence.trim())throw Error('Add evidence, a blocker, or a reason for the selected status.');}return out;}
export function validateRecord(r){if(!r.title.trim()||!r.context.trim()||!r.hypothesis.trim())throw Error('Add a title, context and question to investigate.');if(r.state==='Reviewed'&&['oracle','experiment','observation','evidence','gaps','reviewer','conclusion'].some(k=>!r[k].trim()))throw Error('Reviewed investigations need an oracle, experiment, observations, evidence reference, explicit coverage gaps, reviewer and conclusion.');return r;}
export function storySignals(w){return w.stories.map(s=>{const current=w.sessions.filter(x=>x.storyId===s.id&&x.revision===s.revision),observed=current.filter(x=>x.notes.some(n=>['Observation','Bug candidate','Coverage','Automated check','Blocked'].includes(n.kind)));const flags=[];if(!s.criteria.trim())flags.push('Acceptance criteria missing');if(!s.examples.trim())flags.push('Acceptance examples missing');if(!s.questions.trim())flags.push('Three-perspective discussion missing');if(!current.length)flags.push('No session for current revision');else if(!observed.length)flags.push('No observations recorded');if(current.some(x=>x.state==='Ended'&&!x.debrief.trim()))flags.push('Debrief missing');if(current.some(x=>x.notes.some(n=>n.kind==='Blocked')))flags.push('Blocker noted — review status');if(s.status==='Done'&&(!s.reviewer.trim()||!s.decision.trim()))flags.push('Decision rationale missing');return{...s,currentSessions:current.length,observedSessions:observed.length,flags};});}
export function recordStatus(r,w){if(!r.storyId)return 'Standalone investigation';const s=w.stories.find(x=>x.id===r.storyId);return !s?'Linked story no longer available':s.revision!==r.storyRevision?'Story changed — revisit this investigation':`Story revision ${r.storyRevision} · current`;}
export function reviewSummary(w){const entries=Object.values(w.gates),evidence=entries.filter(g=>g.state==='Evidence recorded').length,blocked=entries.filter(g=>g.state==='Blocked').length,open=entries.filter(g=>g.state==='Not reviewed').length;return{evidence,blocked,open,message:blocked?'Blockers recorded — discuss before release':open?'Review incomplete — unknowns remain':'Review documented — release decision remains with the team'};}
export function humanReport(h,w){const out=[`# ReleaseRadar · Human testing & release review`,`Release: ${h.release||'Not specified'}`,`Build: ${h.build||'Not specified'}`,`Exported: ${new Date().toISOString()}`,'User-recorded investigation notes and evidence references. This report does not execute tests or approve a release.','## Release review',reviewSummary(h).message];for(const [id,label]of gates)out.push(`### ${label}`,`Status: ${h.gates[id].state}`,h.gates[id].evidence||'No evidence or rationale recorded.');out.push('## HIST investigations');if(!h.records.length)out.push('No investigations recorded.');for(const r of h.records){out.push(`### ${r.title}`,`${r.state} · ${r.at}`,recordStatus(r,w));for(const k of recordFields.filter(k=>k!=='title'))out.push(`**${k[0].toUpperCase()+k.slice(1)}:** ${r[k]||'Not recorded'}`);}out.push('## Agile story evidence');for(const s of storySignals(w))out.push(`### ${s.title} · ${s.status} · revision ${s.revision}`,`Priority: ${s.priority} · ${s.observedSessions} sessions with observations for the current revision`,...s.flags.map(x=>`- ${x}`),s.flags.length?'':'No missing fields flagged; this is not proof of adequate testing.');if(!w.stories.length)out.push('No sprint stories in this browser.');return out.join('\n\n');}

export function reviseRecord(previous,next){const changed=previous&&(['storyId','storyRevision',...recordFields.filter(k=>!['reviewer','conclusion','next'].includes(k))].some(k=>previous[k]!==next[k]));return changed&&previous.state==='Reviewed'?{...next,state:'Investigating',reviewer:'',conclusion:''}:next;}
